package edu.ankara.audiometer.ui;
import edu.ankara.audiometer.application.*;import edu.ankara.audiometer.domain.config.AudiometryConfig;import edu.ankara.audiometer.infrastructure.serial.*;import edu.ankara.audiometer.ui.controller.MainController;import javafx.application.Application;import javafx.scene.Scene;import javafx.stage.Stage;
public final class AudiometerApp extends Application { public void start(Stage stage){ var useCase=new AudiometryUseCase(AudiometryConfig.defaults(),new FakeSerialGateway()); var root=new MainController(useCase).root(); var scene=new Scene(root,1280,820); var css=getClass().getResource("/edu/ankara/audiometer/ui/theme/Styles.css"); if(css!=null) scene.getStylesheets().add(css.toExternalForm()); stage.setTitle("Odyometre Sistemi Tasarımı ve Testi"); stage.setScene(scene); stage.show(); } public static void main(String[] args){ launch(args); } }
